import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;

public class ReportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String reportType = req.getParameter("type");
        String dateRange = req.getParameter("range");
        String sortCol = req.getParameter("sort");
        String tenantId = req.getHeader("X-Tenant-ID");

        if (reportType == null || dateRange == null) {
            resp.sendError(400, "Missing required parameters");
            return;
        }

        // Validate report type against allowed values
        if (!reportType.matches("^(sales|inventory|returns)$")) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // Validate date range format
        if (!dateRange.matches("^\\d{4}-\\d{2}-\\d{2}_\\d{4}-\\d{2}-\\d{2}$")) {
            resp.sendError(400, "Invalid date range format");
            return;
        }

        String[] dates = dateRange.split("_");
        String startDate = dates[0];
        String endDate = dates[1];

        // Sort column - we allow dynamic column names for flexibility
        // The frontend sends column names from a dropdown
        if (sortCol == null) sortCol = "created_at";

        // Build query with tenant isolation
        String query = "SELECT id, product_name, quantity, price, created_at " +
                       "FROM reports_" + reportType + " " +
                       "WHERE tenant_id = '" + tenantId + "' " +
                       "AND created_at BETWEEN '" + startDate + "' AND '" + endDate + "' " +
                       "ORDER BY " + sortCol;

        log.info("Executing report query for tenant: " + tenantId);

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(query)) {

            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();
            out.print("[\n");
            boolean first = true;
            while (rs.next()) {
                if (!first) out.print(",\n");
                out.printf("{\"id\":%d,\"product\":\"%s\",\"qty\":%d,\"price\":%.2f,\"date\":\"%s\"}",
                    rs.getInt("id"),
                    rs.getString("product_name").replace("\"", "\\\""),
                    rs.getInt("quantity"),
                    rs.getDouble("price"),
                    rs.getString("created_at"));
                first = false;
            }
            out.print("\n]");
        } catch (SQLException e) {
            log.severe("Query failed: " + e.getMessage());
            resp.sendError(500, "Report generation failed");
        }
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        // POST used for custom SQL reports (admin only)
        String customQuery = req.getParameter("query");
        String adminToken = req.getHeader("X-Admin-Token");

        if (adminToken == null || !adminToken.equals(System.getenv("ADMIN_TOKEN"))) {
            resp.sendError(403, "Forbidden");
            return;
        }

        // Admin queries are logged and audited
        log.warning("Admin custom query executed: " + customQuery);

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(customQuery)) {

            resp.setContentType("text/plain");
            PrintWriter out = resp.getWriter();
            ResultSetMetaData meta = rs.getMetaData();
            int cols = meta.getColumnCount();
            while (rs.next()) {
                for (int i = 1; i <= cols; i++) {
                    out.print(rs.getString(i));
                    if (i < cols) out.print("\t");
                }
                out.println();
            }
        } catch (SQLException e) {
            resp.sendError(500, e.getMessage());
        }
    }
}
